share_of <- function(x, value) {
  mean(x == value, na.rm = TRUE)
}

summarize_trips <- function(df, group) {
  df |>
    summarize(
      trips = n(),
      median_minutes = median(duration_min),
      .by = {{ group }}
    )
}

duration_histogram <- function(df, binwidth = 2) {
  ggplot(df, aes(x = duration_min)) +
    geom_histogram(binwidth = binwidth) +
    labs(title = str_glue("{nrow(df)} trips"))
}
